// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;

    function setUp() public {
        c = new Size();
    }

    function testFuzz_property(address actor, uint256 warpTime) public {
        // keep parameters in an admissible, wide domain
        vm.assume(actor != address(0));
        vm.warp(bound(warpTime, 0, block.timestamp + 365 days));

        // drive the public entry `paused` from an arbitrary caller at an arbitrary time
        vm.prank(actor);
        bool pausedFlag = c.paused();

        // the reference contract reports the actual (unpaused) state for EVERY input;
        // the mutant negates it and reports true
        assertTrue(!pausedFlag);
    }
}
